var p = new IdempotentProcessor();
int runs = 0;
int r1 = p.Process("m1", () => ++runs);
int r2 = p.Process("m1", () => ++runs);   // duplicate delivery
Cj.Eq(r1, 1, "first run");
Cj.Eq(r2, 1, "repeat returns cached result");
Cj.Eq(runs, 1, "work executed exactly once");

var ids = Enumerable.Range(0, 20).Select(i => $"msg-{i}").ToList();
int runs = 0;
var delta = IdempotentProcessor.DeliverAll(ids, id => IdempotentProcessor.RunTracked(id, () => ++runs), 3);
Cj.Eq(delta[0], 20, "20 unique messages = 20 runs despite 60 deliveries");
